import { ErrorBox, Card } from "march/ui"

// kayıp kedi: her denemede başka bir yere bakılır, üçüncüsünde kedi bulunur
const PLACES = ["Koltuğun altında yok.", "Dolabın içinde de yok.", "Balkonda da yok."]

export function LostCat() {
  let $tries = 0
  return <Card title="Pamuk nerede?">
    {() => $tries >= 3
      ? <p sx={{ text: "lg" }}>🐈 Pamuk kutunun içinde uyuyormuş!</p>
      : <ErrorBox title="Kedi bulunamadı" message={PLACES[$tries]} retry={() => $tries++} retryLabel="Başka yere bak" />}
  </Card>
}

import { ErrorBox, Card, Skeleton, Button } from "march/ui"

// sipariş paneli: yükleme bir hata nesnesiyle düşer; yeniden dene isteği tekrarlar, ikinci deneme başarılı olur
export function OrdersPanel() {
  let $state: "loading" | "error" | "done" = "loading"
  let $err: Error | null = null
  let $attempt = 0
  const load = () => {
    $state = "loading"
    $attempt++
    setTimeout(() => {
      if ($attempt < 2) { $err = new Error(`Zaman aşımı: /api/orders (${$attempt}. deneme)`); $state = "error" }
      else $state = "done"
    }, 600)
  }
  load()
  return <Card title="Son siparişler">
    {() => $state === "loading" ? <Skeleton lines={3} />
      : $state === "error" ? <ErrorBox title="Siparişler yüklenemedi" error={() => $err} retry={load} />
      : <div sx={{ flex: "col", gap: 1 }}>
          <span>#1042 · 3 ürün · 412 ₺</span>
          <span>#1041 · 1 ürün · 89 ₺</span>
          <Button size="sm" variant="ghost" on:click={() => { $attempt = 0; load() }}>Baştan dene</Button>
        </div>}
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { ErrorBoxLab } from "./ErrorBoxLab.tsx"

// ErrorBoxLab'in testleri: kaydedince Testler sekmesinde çalışır
test("Error nesnesinin message'ı, metin hatası ve message gösterilir", () => {
  const s = renderTest(() => <ErrorBoxLab />)
  expect(s.sees("Bağlantı reddedildi")).toBe(true)
  expect(s.sees("Dosya bulunamadı (404)")).toBe(true)
  expect(s.sees("Yalnız message: error verilmedi.")).toBe(true)
})

test("retry düğmesi çağırır; erişimci hatası güncellenir", async () => {
  const s = renderTest(() => <ErrorBoxLab />)
  await s.click("Kodu artır")
  expect(s.sees("Yeniden deneme: 1")).toBe(true)
  expect(s.sees("Sunucu hatası (501)")).toBe(true)
})

test("hata kutusu role=alert ve class köke eklenir", () => {
  const s = renderTest(() => <ErrorBoxLab />)
  const box = s.get(".lab-error")
  expect(box?.getAttribute("role")).toBe("alert")
  expect(box?.querySelector(".m-errorbox-retry")?.textContent).toContain("Yenile")
})

test("retry verilmezse düğme yok", () => {
  const s = renderTest(() => <ErrorBoxLab />)
  const text = s.find("Dosya bulunamadı (404)")?.closest(".m-errorbox")
  expect(text?.querySelector("button")).toBe(null)
})
